  ('PT180', 'pt180', 'uav', NULL, '{"Net Weight": "50kg", "Dimensions": "Wingspan 8000mm, Length 3930mm", "Maximum Take-Off Weight": "180kg", "Take-Off Method": "Runway Takeoff and Landing", "Recovery Method": "Autonomous Return to Base", "Maximum Endurance": "8h (continuous long-range security operations)", "Maximum Range": "800km (long-range security patrol)", "Maximum Control Distance": "200km (ground station control)", "Take-Off Requirements": "100m minimum runway distance", "Cruising Speed": "100km/h (stable security patrol speed)", "Maximum Speed": "180km/h (rapid response security missions)", "Cruising Altitude": "&le;3000m", "Maximum Ceiling": "5000m", "Wind Resistance": "Level 5 (take-off), Level 7 (in flight)", "Reconnaissance Equipment": "Electro-optical pod (situational awareness)", "Communication System": "Data Link (reliable long-range transmission)", "Control Method": "Ground Station (authorized personnel operation)", "Payload Hardpoints": "4 points", "Payload Capacity per Hardpoint": "30kg", "Payload Type": "Legitimate security response &amp; support equipment", "Maximum Payload": "130kg (legitimate security support equipment)", "Swarm Coordination Capability": "Supported (synchronized security monitoring)", "Self-protection Function": "Autonomous return to base (equipment safety)", "Propulsion System": "Gasoline (high-power for long-endurance missions)", "Key Features": "High payload, long endurance, integrated reconnaissance &amp; security response"}'::jsonb, '{"en": {"overview": "Product Overview PT180 is a high-performance long-endurance security unmanned aerial system, exclusively designed for legitimate national defense, border security, humanitarian relief and professional long-range security support tasks complying with international laws. This system is only supplied to authorized defense, security and government agencies (unauthorized use is strictly prohibited), and is applicable in regions without mandatory market access certification req